import config from '../config/youtube';

class YouTubeService {
  constructor() {
    this.apiKey = config.youtube.apiKey;
    this.channelId = config.youtube.channelId;
    this.baseURL = 'https://www.googleapis.com/youtube/v3';
  }

  async makeRequest(endpoint, params = {}) {
    try {
      const queryParams = new URLSearchParams({
        key: this.apiKey,
        ...params
      });

      const response = await fetch(`${this.baseURL}/${endpoint}?${queryParams}`);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error('❌ Erro na requisição YouTube:', error);
      throw error;
    }
  }

  // Buscar transmissões ao vivo ATIVAS
  async getLiveStreams() {
    try {
      console.log('🔴 Buscando transmissões ao vivo ATIVAS...');
      
      const data = await this.makeRequest('search', {
        channelId: this.channelId,
        eventType: 'live',
        type: 'video',
        maxResults: 1,
        order: 'date',
        part: 'snippet'
      });

      console.log('📊 Resultado live ativa:', data);
      
      if (data.items && data.items.length > 0) {
        const liveStream = data.items[0];
        console.log('🎯 Live ATIVA encontrada:', liveStream.snippet.title);
        return data;
      } else {
        console.log('📡 Nenhuma live ATIVA no momento');
        return { items: [] };
      }
    } catch (error) {
      console.error('❌ Erro ao buscar lives ativas:', error);
      return { items: [] };
    }
  }

  // Buscar LIVES PASSADAS que viraram vídeos
  async getRecentVideos(limit = 6) {
    try {
      console.log('📹 Buscando LIVES PASSADAS...');
      
      // Primeiro busca os vídeos mais recentes do canal
      const searchData = await this.makeRequest('search', {
        channelId: this.channelId,
        type: 'video',
        maxResults: limit + 10,
        order: 'date',
        part: 'snippet'
      });

      console.log('📊 Resultado busca vídeos:', searchData);

      if (!searchData.items || searchData.items.length === 0) {
        console.log('⚠️ Nenhum vídeo encontrado, usando fallback');
        return this.getFallbackVideos(limit);
      }

      // Pega os IDs dos vídeos para buscar detalhes
      const videoIds = searchData.items.map(item => item.id.videoId).join(',');
      
      // Busca detalhes completos dos vídeos
      const videosData = await this.makeRequest('videos', {
        id: videoIds,
        part: 'snippet,contentDetails,statistics,liveStreamingDetails'
      });

      console.log('📊 Detalhes dos vídeos:', videosData);

      // Processa os vídeos (agora pega todos, não só lives)
      const processedVideos = videosData.items.slice(0, limit).map((video, index) => {
        const searchItem = searchData.items.find(item => item.id.videoId === video.id);
        
        return {
          id: video.id,
          videoId: video.id,
          titulo: video.snippet.title,
          descricao: video.snippet.description,
          thumbnail: video.snippet.thumbnails.medium?.url || video.snippet.thumbnails.default?.url,
          data: new Date(video.snippet.publishedAt).toLocaleDateString('pt-BR'),
          duracao: video.contentDetails?.duration || 'PT1H0M',
          duracaoLegivel: this.formatDuration(video.contentDetails?.duration) || '1:00:00',
          visualizacoes: video.statistics?.viewCount || '0',
          foiLive: !!video.liveStreamingDetails
        };
      });

      console.log('✅ Vídeos processados:', processedVideos);
      return processedVideos;

    } catch (error) {
      console.error('❌ Erro ao buscar vídeos:', error);
      return this.getFallbackVideos(limit);
    }
  }

  // Formatar duração ISO 8601 para legível
  formatDuration(duration) {
    if (!duration || duration === 'P0D') return '0:00';
    
    const match = duration.match(/PT(\d+H)?(\d+M)?(\d+S)?/);
    if (!match) return duration;

    const hours = (match[1] || '').replace('H', '');
    const minutes = (match[2] || '').replace('M', '');
    const seconds = (match[3] || '').replace('S', '');

    if (hours) {
      return `${hours}:${minutes.padStart(2, '0')}:${seconds.padStart(2, '0')}`;
    }
    return `${minutes || '0'}:${seconds.padStart(2, '0')}`;
  }

  // ========== FALLBACK DATA ==========
  getFallbackVideos(limit = 6) {
    console.log('🔄 Usando vídeos fallback pré-configurados');
    
    const fallbackVideos = [
      {
        id: 'video1',
        titulo: 'Congresso do Círculo de Oração - Colunas de Fé',
        data: '25 Jul 2025',
        videoId: 'rT8YqGItaR0',
        thumbnail: 'https://img.youtube.com/vi/rT8YqGItaR0/hqdefault.jpg',
        duracao: '2:07:55',
        visualizacoes: '131',
        duracaoLegivel: '2:07:55',
        foiLive: true
      },
      {
        id: 'video2', 
        titulo: 'Congresso de Jovens (Dia 02)',
        data: '24 Mai 2025',
        videoId: 'QQc8996nOvM',
        thumbnail: 'https://img.youtube.com/vi/QQc8996nOvM/hqdefault.jpg',
        duracao: '2:52:45',
        visualizacoes: '131',
        duracaoLegivel: '2:52:45',
        foiLive: true
      },
      {
        id: 'video3',
        titulo: 'Culto de Ação de Graça',
        data: '16 Ago 2025',
        videoId: '1U0T3ZFEI3w',
        thumbnail: 'https://img.youtube.com/vi/1U0T3ZFEI3w/hqdefault.jpg',
        duracao: '3:31:40',
        visualizacoes: '98',
        duracaoLegivel: '3:31:40',
        foiLive: true
      },
      {
        id: 'video4',
        titulo: 'Congresso Infantil - Dia 02',
        data: '21 Jun 2025',
        videoId: 'WFS8EDhs9iw',
        thumbnail: 'https://img.youtube.com/vi/WFS8EDhs9iw/hqdefault.jpg',
        duracao: '2:13:30',
        visualizacoes: '91',
        duracaoLegivel: '2:13:30',
        foiLive: true
      },
      {
        id: 'video5',
        titulo: '14° Aniversário da Igreja | Dia 01',
        data: '16 Nov 2024',
        videoId: '4vmylFlIL20',
        thumbnail: 'https://img.youtube.com/vi/4vmylFlIL20/hqdefault.jpg',
        duracao: '2:35:25',
        visualizacoes: '77',
        duracaoLegivel: '2:35:25',
        wasLive: true
      },
      {
        id: 'video6',
        titulo: 'Culto de Missão',
        data: '14 Set 2025',
        videoId: 'KOaB1TWnT2w',
        thumbnail: 'https://img.youtube.com/vi/KOaB1TWnT2w/hqdefault.jpg',
        duracao: '2:26:40',
        visualizacoes: '94',
        duracaoLegivel: '2:26:40',
        foiLive: true
      }
    ];
    return fallbackVideos.slice(0, limit);
  }
}

export default new YouTubeService();
